 function pointerUpdate(){const hit=candleHit(),key=hit?hit.slot+':'+hit.b.t:'';document.querySelectorAll('.guns-crosshair').forEach(e=>e.style.display='none');if(hit){const line=document.getElementById('guns-crosshair-'+hit.slot);if(line){line.style.display='block';line.style.left=hit.x+'px';}put('guns-candle-'+hit.slot,esc(newsTime(hit.b.t)+' · O '+px(hit.b.o)+' H '+px(hit.b.h)+' L '+px(hit.b.l)+' C '+px(hit.b.c)+' · Vol '+(Number.isFinite(hit.b.v)?hit.b.v:'unknown')));}if(key!==lastHoverKey&&E.cfg().hoverCandle&&!hoverFrame)hoverFrame=requestAnimationFrame(()=>{hoverFrame=null;live();});lastHoverKey=key;}
