  const interval=canvas.dataset.chartFrame==='d'?86400000:Number(canvas.dataset.chartFrame)*60000,forming=b=>typeof b.t==='string'?b.t>=C.day(a.now()):b.t+interval>a.now();const slot=slots[Number(canvas.dataset.chartSlot)],range=ranges.get((slot.inst?.symbol||'')+':'+slot.frame)||{count:80,offset:0},end=Math.max(1,bars.length-Math.min(range.offset,Math.max(0,bars.length-1))),v=bars.slice(Math.max(0,end-range.count),end),closed=bars.filter(b=>!forming(b)&&b.complete!==false),indices=new Map(closed.map((b,i)=>[b.t,i])),studies=C.studies(closed).map(s=>v.map(b=>indices.has(b.t)?s[indices.get(b.t)]:null));const prices=[...v.flatMap(b=>[b.l,b.h]),...Object.values(levels||{}).filter(Number.isFinite)];let lo=Math.min(...prices),hi=Math.max(...prices);const pad=Math.max((hi-lo)*.08,.01);lo-=pad;hi+=pad;const plotW=Math.max(1,width-55),dx=plotW/v.length,y=p=>24+(hi-p)/(hi-lo)*(height-125),x=i=>(i+.5)*dx;
